CREATE TABLE finance.accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),owner_type text NOT NULL CHECK(owner_type IN('platform','user','business','provider')),owner_id uuid,code varchar(80) NOT NULL,kind text NOT NULL CHECK(kind IN('asset','liability','equity','revenue','expense')),currency char(3) NOT NULL DEFAULT 'IRR' CHECK(currency='IRR'),state text NOT NULL DEFAULT 'active' CHECK(state IN('active','frozen','closed')),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,code));
CREATE TABLE finance.journal_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),idempotency_key varchar(120) NOT NULL,reference_type varchar(60) NOT NULL,reference_id varchar(120) NOT NULL,description varchar(500) NOT NULL,posted_at timestamptz NOT NULL DEFAULT clock_timestamp(),created_by uuid,metadata jsonb NOT NULL DEFAULT '{}',UNIQUE(tenant_id,idempotency_key));
CREATE TABLE finance.postings(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES platform.tenants(id),journal_id uuid NOT NULL REFERENCES finance.journal_entries(id),account_id uuid NOT NULL REFERENCES finance.accounts(id),currency char(3) NOT NULL DEFAULT 'IRR' CHECK(currency='IRR'),debit bigint NOT NULL DEFAULT 0 CHECK(debit>=0),credit bigint NOT NULL DEFAULT 0 CHECK(credit>=0),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK((debit>0 AND credit=0)OR(credit>0 AND debit=0)));
CREATE INDEX finance_posting_account_idx ON finance.postings(tenant_id,account_id,created_at DESC,id DESC);CREATE INDEX finance_journal_reference_idx ON finance.journal_entries(tenant_id,reference_type,reference_id);
CREATE FUNCTION finance.assert_balanced_journal()RETURNS trigger LANGUAGE plpgsql AS $$DECLARE d numeric;c numeric;BEGIN SELECT coalesce(sum(debit),0),coalesce(sum(credit),0)INTO d,c FROM finance.postings WHERE journal_id=NEW.journal_id;IF d=0 OR d<>c THEN RAISE EXCEPTION 'finance_journal_unbalanced';END IF;RETURN NEW;END$$;
CREATE CONSTRAINT TRIGGER finance_journal_balanced AFTER INSERT OR UPDATE ON finance.postings DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION finance.assert_balanced_journal();
CREATE FUNCTION finance.reject_ledger_mutation()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'finance_ledger_immutable';END$$;CREATE TRIGGER finance_journal_immutable BEFORE UPDATE OR DELETE ON finance.journal_entries FOR EACH ROW EXECUTE FUNCTION finance.reject_ledger_mutation();CREATE TRIGGER finance_posting_immutable BEFORE UPDATE OR DELETE ON finance.postings FOR EACH ROW EXECUTE FUNCTION finance.reject_ledger_mutation();
CREATE TABLE finance.wallets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),user_id uuid NOT NULL REFERENCES identity.users(id),account_id uuid NOT NULL REFERENCES finance.accounts(id),currency char(3) NOT NULL DEFAULT 'IRR' CHECK(currency='IRR'),state text NOT NULL DEFAULT 'active' CHECK(state IN('active','frozen','closed')),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,user_id,currency),UNIQUE(account_id));
CREATE TABLE finance.wallet_holds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),wallet_id uuid NOT NULL REFERENCES finance.wallets(id),amount bigint NOT NULL CHECK(amount>0),reason varchar(120) NOT NULL,reference_id varchar(120) NOT NULL,state text NOT NULL DEFAULT 'active' CHECK(state IN('active','captured','released','expired')),expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,wallet_id,reference_id));CREATE INDEX finance_hold_active_idx ON finance.wallet_holds(tenant_id,wallet_id,expires_at)WHERE state='active';
CREATE TABLE finance.payment_providers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),code varchar(40) NOT NULL,display_name varchar(100) NOT NULL,enabled boolean NOT NULL DEFAULT true,health_state text NOT NULL DEFAULT 'healthy' CHECK(health_state IN('healthy','degraded','offline')),priority smallint NOT NULL DEFAULT 100,fee_bps integer NOT NULL DEFAULT 0 CHECK(fee_bps BETWEEN 0 AND 10000),config_key varchar(120) NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,code));
CREATE TABLE finance.payment_intents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),user_id uuid NOT NULL REFERENCES identity.users(id),amount bigint NOT NULL CHECK(amount>0),currency char(3) NOT NULL DEFAULT 'IRR' CHECK(currency='IRR'),purpose varchar(80) NOT NULL,provider_id uuid NOT NULL REFERENCES finance.payment_providers(id),provider_reference varchar(160),idempotency_key varchar(120) NOT NULL,state text NOT NULL CHECK(state IN('created','pending','authorized','captured','failed','cancelled','refunded','partially_refunded')),failure_code varchar(80),captured_at timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,idempotency_key),UNIQUE(tenant_id,provider_id,provider_reference));CREATE INDEX finance_payment_user_idx ON finance.payment_intents(tenant_id,user_id,created_at DESC);CREATE INDEX finance_payment_pending_idx ON finance.payment_intents(tenant_id,state,created_at)WHERE state IN('created','pending','authorized');
CREATE TABLE finance.provider_events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES platform.tenants(id),provider_id uuid NOT NULL REFERENCES finance.payment_providers(id),event_id varchar(160) NOT NULL,event_type varchar(80) NOT NULL,payload jsonb NOT NULL,signature_valid boolean NOT NULL,received_at timestamptz NOT NULL DEFAULT clock_timestamp(),processed_at timestamptz,UNIQUE(tenant_id,provider_id,event_id));
CREATE TABLE finance.refunds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),payment_intent_id uuid NOT NULL REFERENCES finance.payment_intents(id),amount bigint NOT NULL CHECK(amount>0),reason varchar(500) NOT NULL,idempotency_key varchar(120) NOT NULL,state text NOT NULL DEFAULT 'requested' CHECK(state IN('requested','approved','processing','succeeded','failed','rejected')),requested_by uuid NOT NULL,approved_by uuid,provider_reference varchar(160),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK(approved_by IS NULL OR approved_by<>requested_by),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE finance.settlement_batches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),provider_id uuid NOT NULL REFERENCES finance.payment_providers(id),period_start timestamptz NOT NULL,period_end timestamptz NOT NULL,expected_amount bigint NOT NULL,actual_amount bigint,state text NOT NULL DEFAULT 'open' CHECK(state IN('open','received','reconciled','exception','closed')),file_checksum char(64),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK(period_end>period_start),UNIQUE(tenant_id,provider_id,period_start,period_end));
CREATE TABLE finance.reconciliation_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),batch_id uuid REFERENCES finance.settlement_batches(id),provider_id uuid NOT NULL REFERENCES finance.payment_providers(id),external_reference varchar(160) NOT NULL,expected_amount bigint NOT NULL,actual_amount bigint NOT NULL,difference bigint GENERATED ALWAYS AS(actual_amount-expected_amount)STORED,tolerance bigint NOT NULL DEFAULT 0 CHECK(tolerance>=0),status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','matched','exception','resolved')),resolution varchar(500),resolved_by uuid,reconciled_at timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,provider_id,external_reference));CREATE INDEX finance_reconciliation_queue_idx ON finance.reconciliation_items(tenant_id,status,created_at)WHERE status IN('pending','exception');
CREATE TABLE finance.installment_plans(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),user_id uuid NOT NULL REFERENCES identity.users(id),reference_type varchar(60) NOT NULL,reference_id varchar(120) NOT NULL,total_amount bigint NOT NULL CHECK(total_amount>0),currency char(3) NOT NULL DEFAULT 'IRR' CHECK(currency='IRR'),state text NOT NULL DEFAULT 'active' CHECK(state IN('draft','active','completed','defaulted','cancelled')),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,reference_type,reference_id));
CREATE TABLE finance.installments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),plan_id uuid NOT NULL REFERENCES finance.installment_plans(id)ON DELETE CASCADE,sequence smallint NOT NULL CHECK(sequence>0),amount bigint NOT NULL CHECK(amount>0),due_at timestamptz NOT NULL,state text NOT NULL DEFAULT 'scheduled' CHECK(state IN('scheduled','due','paid','overdue','waived')),payment_intent_id uuid REFERENCES finance.payment_intents(id),paid_at timestamptz,UNIQUE(plan_id,sequence));CREATE INDEX finance_installment_due_idx ON finance.installments(tenant_id,state,due_at)WHERE state IN('scheduled','due','overdue');
DO $$ DECLARE table_name text;BEGIN FOREACH table_name IN ARRAY ARRAY['accounts','journal_entries','postings','wallets','wallet_holds','payment_providers','payment_intents','provider_events','refunds','settlement_batches','reconciliation_items','installment_plans','installments']LOOP EXECUTE format('ALTER TABLE finance.%I ENABLE ROW LEVEL SECURITY',table_name);EXECUTE format('ALTER TABLE finance.%I FORCE ROW LEVEL SECURITY',table_name);EXECUTE format('CREATE POLICY %I ON finance.%I USING(tenant_id=NULLIF(current_setting(''app.current_tenant_id'',true),'''')::uuid)WITH CHECK(tenant_id=NULLIF(current_setting(''app.current_tenant_id'',true),'''')::uuid)',table_name||'_tenant_isolation',table_name);END LOOP;END$$;
